import{_ as t,a}from"./chunks/tokeness-api-keys-dark-16x9.lsCoxlJJ.js";import{_ as i,o as s,c as o,a4 as r}from"./chunks/framework.DCsBdTIw.js";const y=JSON.parse('{"title":"API Keys","description":"Tokeness API key creation, naming, quota, rotation, and environment variable configuration.","frontmatter":{"title":"API Keys","description":"Tokeness API key creation, naming, quota, rotation, and environment variable configuration."},"headers":[],"relativePath":"guide/api-keys.md","filePath":"guide/api-keys.md","lastUpdated":1784332800000}'),n={name:"guide/api-keys.md"};function d(l,e,c,h,p,k){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="api-keys" tabindex="-1">API Keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API Keys&quot;">​</a></h1><p>API keys are the credentials for calling Tokeness. Each key should have a clear purpose; avoid sharing one key across multiple projects.</p><figure class="tokeness-shot"><div class="tokeness-shot-frame"><img class="tokeness-shot-light" src="'+t+'" alt="Tokeness API Keys page"><img class="tokeness-shot-dark" src="'+a+`" alt="Tokeness API Keys page"></div><figcaption>API Keys page</figcaption></figure><h2 id="create-a-key" tabindex="-1">Create a Key <a class="header-anchor" href="#create-a-key" aria-label="Permalink to &quot;Create a Key&quot;">​</a></h2><ol><li>Sign in to <a href="https://tokeness.ai" target="_blank" rel="noreferrer">tokeness.ai</a>.</li><li>Open &quot;API Keys&quot; in the left navigation of the console.</li><li>Click create or add a key.</li><li>Fill in the name, quota, group, or model scope.</li><li>Save the key immediately after creation.</li></ol><p>Before connecting to production workloads, you can create two keys first:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Configuration</th></tr></thead><tbody><tr><td>Testing</td><td>Small quota, easy to trial and error</td></tr><tr><td>Production</td><td>Separate key, avoid mixing with testing</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Security Reminder</p><p>API keys are sensitive credentials. Never write keys into frontend code, public repositories, screenshots, ticket images, or group chat messages.</p></div><h2 id="list-fields" tabindex="-1">List Fields <a class="header-anchor" href="#list-fields" aria-label="Permalink to &quot;List Fields&quot;">​</a></h2><p>The API Keys page shows the main management info for each key:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td>Key purpose name, e.g. development, production, or a specific customer</td></tr><tr><td>Status</td><td>Whether the key is enabled</td></tr><tr><td>API Key</td><td>Masked key, used to confirm the right credential is selected</td></tr><tr><td>Quota</td><td>Current key quota limit</td></tr><tr><td>Group</td><td>Model or billing group the key belongs to</td></tr><tr><td>Models</td><td>Available model scope for the current key</td></tr><tr><td>IP Restriction</td><td>Whether calling source IPs are restricted</td></tr><tr><td>Created At</td><td>Key creation time</td></tr><tr><td>Last Used</td><td>Most recent call time</td></tr><tr><td>Expiry</td><td>Key expiry policy</td></tr></tbody></table><h2 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Example key name</th></tr></thead><tbody><tr><td>Local development</td><td><code>dev-local</code></td></tr><tr><td>Production service</td><td><code>prod-api-gateway</code></td></tr><tr><td>Customer project</td><td><code>client-acme-prod</code></td></tr><tr><td>Automation task</td><td><code>n8n-workflows</code></td></tr></tbody></table><h2 id="quota-strategy" tabindex="-1">Quota Strategy <a class="header-anchor" href="#quota-strategy" aria-label="Permalink to &quot;Quota Strategy&quot;">​</a></h2><p>Set a small quota for development and test keys. Set limits on production keys based on business volume. In channel or multi-customer scenarios, use a separate key for each customer to track consumption.</p><h2 id="rotate-keys" tabindex="-1">Rotate Keys <a class="header-anchor" href="#rotate-keys" aria-label="Permalink to &quot;Rotate Keys&quot;">​</a></h2><p>When a key is leaked, a team member leaves, a project is handed off, or an environment is migrated, create a new key and replace the old configuration. After confirming the new key works, disable the old key.</p><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>Server-side projects use environment variables to store keys:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKENESS_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKENESS_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev/v1</span></span></code></pre></div><p>Do not commit <code>.env</code> files to Git repositories.</p>`,21)])])}const g=i(n,[["render",d]]);export{y as __pageData,g as default};
